mapper.select:
SELECT pcv.violation_id violationId, pc.license, pc.brand, pc.model, pc.seat_num seatNum,
       pcv.date violationTime, pcv.address, pcv.deduction, pcv.fine, pcv.content
FROM pubcar_car_violation pcv
LEFT JOIN pubcar_car pc ON pc.car_id = pcv.car_id AND pc.status_cd = '0'
WHERE pcv.driver_id IS NOT NULL
    AND pcv.community_id = #{communityId}
    AND pcv.handle_status = #{handleStatus}

        AND pcv.driver_id = #{driverId}

ORDER BY pcv.create_time DESC

    limit #{page}, #{row}

select b_id bId, violation_id violationId, `date`, address, driver, content, deduction, fine, car_id carId, driver_id driverId, handle_status handleStatus, community_id communityId
from business_pubcar_car_violation


        b_id= #{bId}


        and operate= #{operate}

mapper.insert:
insert into pubcar_car_violation(violation_id, `date`, address, driver, content, deduction, fine, car_id, driver_id, handle_status, b_id, community_id, status_cd)
select violation_id, date, address, driver, content, deduction, fine, car_id, driver_id, handle_status, b_id, community_id, '0'
from business_pubcar_car_violation


        b_id= #{bId}


        and operate= #{operate}

mapper.select:
select t.date,t.address,t.driver,t.deduction,t.fine,t.create_time,t.create_time createTime,t.b_id,t.b_id
bId,t.community_id,t.community_id communityId,t.content,t.violation_id,t.violation_id
violationId,t.car_id,t.car_id carId
from pubcar_car_violation t


        t.date= #{date}


        and t.address= #{address}


        and t.driver= #{driver}


        and t.deduction= #{deduction}


        and t.fine= #{fine}


        and t.create_time= #{createTime}


        and t.b_id= #{bId}


        and t.community_id= #{communityId}


        and t.content= #{content}


        and t.violation_id= #{violationId}


        and t.car_id= #{carId}


        and t.status_cd= #{statusCd}


order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update pubcar_car_violation t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    ,t.handle_status= #{handleStatus}



        t.b_id= #{bId}


        and t.violation_id= #{violationId}

mapper.select:
select count(1) count
from pubcar_car_violation t
where t.status_cd = '0' and t.driver_id IS NOT NULL
and t.handle_status= #{handleStatus}
and t.community_id= #{communityId}

    and t.driver_id = #{driverId}
